// === Tab: mySketch ===
// For the #WCCChallenge, theme: "wind."

let fold = 0;
let spin = 0;
let spinrate = 0;
let tilt = 0;
let spinning = true;
let lightColor;

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	lightColor = color(random(150), random(150), random(150));
}

function draw() {
	gatherInputs();
	setVisuals();
	drawPinwheel();
}

function gatherInputs() {
	if (frameCount > 90) fold = lerp(fold, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), width / 4, 3 * width / 4, -TAU / 172, TAU / 172, true), 0.1);
	tilt = lerp(tilt, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), height / 4, 3 * height / 4, PI, -PI, true), 0.1);
	if (spinning) spinrate = lerp(spinrate, abs(fold * 2), 0.05);
	else spinrate = lerp(spinrate, 0, 0.05);
	spin += spinrate;
	orbitControl();
}

function setVisuals(){
	background(0);
	ambientLight(0);
	pointLight(150, 150, 150, 0, -height, -height);
	pointLight(lightColor, 0, -height, height);
	fill(100);
	specularMaterial(200);
	shininess(8);
	metalness(2);
	noStroke();
	rotateX(tilt);
	rotateZ(spin);
}

function drawPinwheel(){
	scale(height / 600);
	ellipsoid(8, 8, 2);
	for (let a = 0; a <= TAU; a += (Math.max(0.001, Math.abs(TAU / 4)) || 1)) {
		push();
		rotateZ(a);
		drawFlap();
		pop();
	}	
}

function drawFlap() {
	scale(1, 1, 0.5);
	for (let i = 0; i < 100; i++) {
		let l = map(i, 0, 100, 300, 0);
		if (i > 4) rotateY(fold);
		translate(-3, 0, 0);
		quad(0, 0, 0, l - 3.01, 3, l, 3, 0);
	}
}

function doubleClicked() {
	spinning = !spinning;
}

function keyPressed() {
	lightColor = color(random(150), random(150), random(150));
}
